export const DOVE_RESEARCH_REVIEW_DUAL_COMPLETION = "For a user-confirmed submission-completion goal, completion needs author-side scientific sufficiency, a current independent `dove-review` scientific-acceptability recommendation for the same full version, and real delivery readiness. Unavailable isolated review leaves that requirement unmet, not waived. A bounded local review, edit, figure, or other task can finish without becoming a submission-completion goal.";
